-- Living Pages core schema. Every tenant table is protected with RLS.
create extension if not exists pgcrypto;
create type public.workspace_role as enum ('owner','admin','editor','viewer');
create type public.record_status as enum ('draft','published','archived');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 80),slug text not null unique,owner_id uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.workspace_members(workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.workspace_role not null default 'viewer',created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table public.sites(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,slug text not null,type text not null default 'business',status public.record_status not null default 'draft',locale text not null default 'en',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(workspace_id,slug));
create table public.pages(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,site_id uuid not null references public.sites(id) on delete cascade,name text not null,slug text not null,page_type text not null,is_homepage boolean not null default false,show_in_navigation boolean not null default true,status public.record_status not null default 'draft',position integer not null default 0 check(position>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(site_id,slug));
create table public.page_blocks(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,page_id uuid not null references public.pages(id) on delete cascade,type text not null,version integer not null default 1 check(version>0),content_props jsonb not null default '{}',style_props jsonb not null default '{}',visibility_props jsonb not null default '{"desktop":true,"tablet":true,"mobile":true}',position integer not null check(position>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.page_versions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,page_id uuid not null references public.pages(id) on delete cascade,version integer not null,snapshot jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(page_id,version));
create table public.brands(id uuid primary key default gen_random_uuid(),workspace_id uuid not null unique references public.workspaces(id) on delete cascade,tokens jsonb not null default '{}',voice jsonb not null default '{}',rules jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.content_items(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,title text not null,type text not null,status public.record_status not null default 'draft',body jsonb not null default '{}',locale text not null default 'en',author_id uuid references auth.users(id),published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.sources(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,type text not null check(type in ('rss','json','manual','mock')),name text not null,config jsonb not null default '{}',enabled boolean not null default false,last_synced_at timestamptz,created_at timestamptz not null default now());
create table public.automations(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,trigger jsonb not null,conditions jsonb not null default '[]',action jsonb not null,approval_mode text not null check(approval_mode in ('suggest','requires_approval')),enabled boolean not null default false,created_at timestamptz not null default now());
create table public.credit_accounts(workspace_id uuid primary key references public.workspaces(id) on delete cascade,balance bigint not null default 0 check(balance>=0),reserved bigint not null default 0 check(reserved>=0),updated_at timestamptz not null default now());
create table public.ai_jobs(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references auth.users(id),action text not null,status text not null check(status in ('pending','running','completed','failed','rejected')),estimated_credits integer not null check(estimated_credits>=0),actual_credits integer check(actual_credits>=0),created_at timestamptz not null default now(),completed_at timestamptz);
create table public.credit_ledger(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid references auth.users(id),amount bigint not null,type text not null check(type in ('grant','reserve','consume','release','refund','expire','adjustment')),reason text not null,ai_job_id uuid references public.ai_jobs(id),metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.domains(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,site_id uuid not null references public.sites(id) on delete cascade,hostname text not null unique,verified_at timestamptz,ssl_status text not null default 'pending',is_primary boolean not null default false,created_at timestamptz not null default now());
create table public.analytics_events(id bigint generated always as identity primary key,workspace_id uuid not null references public.workspaces(id) on delete cascade,site_id uuid not null references public.sites(id) on delete cascade,event_name text not null,path text not null,anonymous_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index sites_workspace_idx on public.sites(workspace_id) where deleted_at is null;create index pages_site_idx on public.pages(site_id,position) where deleted_at is null;create index blocks_page_idx on public.page_blocks(page_id,position);create index content_workspace_idx on public.content_items(workspace_id,status);create index ledger_workspace_idx on public.credit_ledger(workspace_id,created_at desc);create index analytics_site_time_idx on public.analytics_events(site_id,created_at desc);
create or replace function public.is_workspace_member(target uuid) returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from public.workspace_members wm where wm.workspace_id=target and wm.user_id=(select auth.uid()))$$;
create or replace function public.can_edit_workspace(target uuid) returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from public.workspace_members wm where wm.workspace_id=target and wm.user_id=(select auth.uid()) and wm.role in ('owner','admin','editor'))$$;
alter table public.profiles enable row level security;alter table public.workspaces enable row level security;alter table public.workspace_members enable row level security;alter table public.sites enable row level security;alter table public.pages enable row level security;alter table public.page_blocks enable row level security;alter table public.page_versions enable row level security;alter table public.brands enable row level security;alter table public.content_items enable row level security;alter table public.sources enable row level security;alter table public.automations enable row level security;alter table public.credit_accounts enable row level security;alter table public.ai_jobs enable row level security;alter table public.credit_ledger enable row level security;alter table public.domains enable row level security;alter table public.analytics_events enable row level security;
create policy profiles_self on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));create policy workspaces_member_read on public.workspaces for select to authenticated using(public.is_workspace_member(id));create policy members_member_read on public.workspace_members for select to authenticated using(public.is_workspace_member(workspace_id));
do $$declare t text;begin foreach t in array array['sites','pages','page_blocks','page_versions','brands','content_items','sources','automations','domains'] loop execute format('create policy %I on public.%I for select to authenticated using(public.is_workspace_member(workspace_id))',t||'_read',t);execute format('create policy %I on public.%I for all to authenticated using(public.can_edit_workspace(workspace_id)) with check(public.can_edit_workspace(workspace_id))',t||'_write',t);end loop;end$$;
create policy credits_read on public.credit_accounts for select to authenticated using(public.is_workspace_member(workspace_id));create policy jobs_read on public.ai_jobs for select to authenticated using(public.is_workspace_member(workspace_id));create policy ledger_read on public.credit_ledger for select to authenticated using(public.is_workspace_member(workspace_id));create policy analytics_read on public.analytics_events for select to authenticated using(public.is_workspace_member(workspace_id));
grant usage on schema public to authenticated;grant select,insert,update,delete on all tables in schema public to authenticated;grant usage,select on all sequences in schema public to authenticated;
